/**
 * opencode Provider Extension
 *
 * Registers opencode as a custom provider with multi-API support.
 * Models use anthropic-messages, openai-responses, openai-completions,
 * or google-generative-ai as appropriate, with per-model baseUrl/api.
 *
 * Model resolution strategy: Stale-While-Revalidate
 *   1. Serve stale immediately: disk cache → embedded models.json (zero-latency)
 *   2. Revalidate in background: live API /models → merge with embedded → cache → hot-swap
 *      Quiet startup sync (sync-policy.ts): only with an API key, only when the
 *      disk cache is older than the TTL (1h, PI_PROVIDER_SYNC_TTL_MS) or the key
 *      changed, and only one pi process at a time (lock file next to the cache).
 *   3. patch.json + custom-models.json applied on top of whichever source won
 *
 * Merge order: [live|cache|embedded] → apply patch.json → merge custom-models.json
 *
 * Usage:
 *   # Set your API key
 *   export OPENCODE_API_KEY=your-api-key
 *
 *   # Run pi with the extension
 *   pi -e /path/to/pi-opencode-provider
 *
 * Then use /model to select from available models
 */

import { getAgentDir, type ExtensionAPI, type ModelRegistry, type ProviderConfig } from "@earendil-works/pi-coding-agent";
import { getAllBuiltinModels } from "@earendil-works/pi-ai/providers/all";
import modelsData from "./models.json" with { type: "json" };
import customModelsData from "./custom-models.json" with { type: "json" };
import patchData from "./patch.json" with { type: "json" };
import deprecatedData from "./deprecated-models.json" with { type: "json" };
import fs from "fs";
import path from "path";
import { acquireModelSync, cacheChangedSinceLoad, markCacheLoaded, writeFileAtomic } from "./sync-policy.ts";

// ─── Types ────────────────────────────────────────────────────────────────────

type Api = "openai-completions" | "openai-responses" | "anthropic-messages" | "google-generative-ai";

interface ThinkingLevelMapValue {
  [level: string]: string | null;
}

interface JsonModel {
  id: string;
  name: string;
  api?: Api;
  baseUrl?: string;
  reasoning: boolean;
  thinkingLevelMap?: ThinkingLevelMapValue;
  input: ("text" | "image")[];
  cost: {
    input: number;
    output: number;
    cacheRead: number;
    cacheWrite: number;
  };
  contextWindow: number;
  maxTokens: number;
  compat?: Record<string, unknown>;
}

interface PatchEntry {
  name?: string;
  api?: Api;
  baseUrl?: string;
  reasoning?: boolean;
  thinkingLevelMap?: ThinkingLevelMapValue;
  input?: ("text" | "image")[];
  cost?: {
    input?: number;
    output?: number;
    cacheRead?: number;
    cacheWrite?: number;
  };
  contextWindow?: number;
  maxTokens?: number;
  compat?: Record<string, unknown>;
}

type PatchData = Record<string, PatchEntry>;

// ─── Patch Application ────────────────────────────────────────────────────────

function applyPatch(model: JsonModel, patch: PatchEntry): JsonModel {
  const result = { ...model };

  if (patch.name !== undefined) result.name = patch.name;
  if (patch.api !== undefined) result.api = patch.api;
  if (patch.baseUrl !== undefined) result.baseUrl = patch.baseUrl;
  if (patch.reasoning !== undefined) result.reasoning = patch.reasoning;
  if (patch.thinkingLevelMap !== undefined) result.thinkingLevelMap = patch.thinkingLevelMap;
  if (patch.input !== undefined) result.input = patch.input;
  if (patch.contextWindow !== undefined) result.contextWindow = patch.contextWindow;
  if (patch.maxTokens !== undefined) result.maxTokens = patch.maxTokens;

  if (patch.cost) {
    result.cost = {
      input: patch.cost.input ?? result.cost.input,
      output: patch.cost.output ?? result.cost.output,
      cacheRead: patch.cost.cacheRead ?? result.cost.cacheRead,
      cacheWrite: patch.cost.cacheWrite ?? result.cost.cacheWrite,
    };
  }
  if (patch.compat) {
    result.compat = { ...(result.compat || {}), ...patch.compat };
  }

  if (!result.reasoning && result.compat?.thinkingFormat) {
    delete result.compat.thinkingFormat;
  }
  if (result.compat && Object.keys(result.compat).length === 0) {
    delete result.compat;
  }

  return result;
}

/** Full pipeline: base models → patch → custom → result */
function buildModels(base: JsonModel[], custom: JsonModel[], patch: PatchData): JsonModel[] {
  const modelMap = new Map<string, JsonModel>();

  // Seed with the base list plus grace-period deprecated models so patch.json
  // entries apply to deprecated models exactly as while the model was live
  // (withDeprecated keeps live data on id conflicts).
  for (const model of withDeprecated(base)) {
    modelMap.set(model.id, model);
  }

  for (const [id, patchEntry] of Object.entries(patch)) {
    const existing = modelMap.get(id);
    if (existing) {
      modelMap.set(id, applyPatch(existing, patchEntry));
    }
  }

  for (const model of custom) {
    const existing = modelMap.get(model.id);
    const patchEntry = patch[model.id];
    if (existing && patchEntry) {
      modelMap.set(model.id, applyPatch(model, patchEntry));
    } else if (existing) {
      modelMap.set(model.id, model);
    } else if (patchEntry) {
      modelMap.set(model.id, applyPatch(model, patchEntry));
    } else {
      modelMap.set(model.id, model);
    }
  }

  return Array.from(modelMap.values());
}

// ─── Stale-While-Revalidate Model Sync ────────────────────────────────────────

const PROVIDER_ID = "opencode";
const BASE_URL = "https://opencode.ai/zen/v1";
const MODELS_URL = `${BASE_URL}/models`;
const CACHE_DIR = path.join(getAgentDir(), "cache");
const CACHE_PATH = path.join(CACHE_DIR, `${PROVIDER_ID}-models.json`);
const LIVE_FETCH_TIMEOUT_MS = 8000;

/** Map models.dev provider.npm to pi API type and base URL. */
const NPM_TO_API: Record<string, { api: Api; baseUrl: string }> = {
  "@ai-sdk/anthropic": { api: "anthropic-messages", baseUrl: "https://opencode.ai/zen" },
  "@ai-sdk/openai": { api: "openai-responses", baseUrl: "https://opencode.ai/zen/v1" },
  "@ai-sdk/google": { api: "google-generative-ai", baseUrl: "https://opencode.ai/zen/v1" },
};
const DEFAULT_API: { api: Api; baseUrl: string } = { api: "openai-completions", baseUrl: "https://opencode.ai/zen/v1" };

/** Transform a model from the opencode /v1/models API. Returns minimal data. */
function transformApiModel(apiModel: any): JsonModel {
  const npm = apiModel.provider?.npm;
  const { api, baseUrl } = (npm && NPM_TO_API[npm]) || DEFAULT_API;
  const rawInput = apiModel.modalities?.input || ["text"];
  // Pi Model type only supports "text" and "image"
  const input: ("text" | "image")[] = rawInput.filter((m: string) => m === "text" || m === "image") as ("text" | "image")[];
  if (!input.includes("text")) input.unshift("text");

  return {
    id: apiModel.id,
    name: apiModel.name || apiModel.id,
    api,
    baseUrl,
    reasoning: apiModel.reasoning || false,
    input,
    cost: {
      input: apiModel.cost?.input || 0,
      output: apiModel.cost?.output || 0,
      cacheRead: apiModel.cost?.cache_read || 0,
      cacheWrite: apiModel.cost?.cache_write || 0,
    },
    contextWindow: apiModel.limit?.context || apiModel.context_length || 131072,
    maxTokens: apiModel.limit?.output || 0,
  };
}

async function fetchLiveModels(apiKey: string, signal?: AbortSignal): Promise<JsonModel[] | null> {
  try {
    const response = await fetch(MODELS_URL, {
      headers: { Authorization: `Bearer ${apiKey}` },
      signal: signal ? AbortSignal.any([AbortSignal.timeout(LIVE_FETCH_TIMEOUT_MS), signal]) : AbortSignal.timeout(LIVE_FETCH_TIMEOUT_MS),
    });
    if (!response.ok) return null;
    const data = await response.json();
    const apiModels = Array.isArray(data) ? data : (data.data || []);
    if (!Array.isArray(apiModels) || apiModels.length === 0) return null;
    return apiModels.map(transformApiModel);
  } catch {
    return null;
  }
}

function loadCachedModels(): JsonModel[] | null {
  try {
    const data = JSON.parse(fs.readFileSync(CACHE_PATH, "utf8"));
    return Array.isArray(data) ? data : null;
  } catch {
    return null;
  }
}

function cacheModels(models: JsonModel[]): void {
  try {
    fs.mkdirSync(CACHE_DIR, { recursive: true });
    // Atomic (tmp + rename): other pi processes may be reading the cache right now.
    writeFileAtomic(CACHE_PATH, JSON.stringify(models, null, 2) + "\n");
  } catch {
    // Cache write failure is non-fatal
  }
}

function mergeWithEmbedded(liveModels: JsonModel[], embeddedModels: JsonModel[]): JsonModel[] {
  const embeddedMap = new Map(embeddedModels.map(m => [m.id, m]));
  const seen = new Set<string>();
  const result: JsonModel[] = [];
  for (const liveModel of liveModels) {
    const embedded = embeddedMap.get(liveModel.id);
    seen.add(liveModel.id);
    if (embedded) {
      // Self-heal: live API pricing is authoritative field-by-field. Prefer the
      // live cost when the API reports it (non-zero); fall back to embedded when
      // the API is silent (0) so curated cacheRead/cacheWrite isn't clobbered and
      // providers whose /models endpoint exposes no pricing keep their curated
      // cost. Curation (reasoning/input/compat/name) still wins via ...embedded.
      result.push({
        ...liveModel,
        ...embedded,
        cost: {
          input: liveModel.cost.input || embedded.cost.input,
          output: liveModel.cost.output || embedded.cost.output,
          cacheRead: liveModel.cost.cacheRead || embedded.cost.cacheRead,
          cacheWrite: liveModel.cost.cacheWrite || embedded.cost.cacheWrite,
        },
        contextWindow: liveModel.contextWindow || embedded.contextWindow,
      });
    } else {
      result.push(liveModel);
    }
  }
  // Append any embedded models that the live API didn't return
  for (const em of embeddedModels) {
    if (!seen.has(em.id)) {
      result.push(em);
    }
  }
  return result;
}

// Grace period for delisted models. When the provider API stops listing a
// model, update-models.js moves its last-known definition into
// deprecated-models.json (stamped with deprecatedAt) instead of dropping it.
// For 14 days the model keeps working here so in-flight sessions and saved
// model settings do not break; afterwards it is evicted permanently.
const DEPRECATED_MODEL_TTL_MS = 14 * 24 * 60 * 60 * 1000;

// Grace-period deprecated models with deprecation metadata stripped.
function activeDeprecatedModels(): JsonModel[] {
  const now = Date.now();
  const result: JsonModel[] = [];
  for (const entry of Object.values(deprecatedData as Record<string, JsonModel & { deprecatedAt?: string }>)) {
    if (!entry?.id) continue;
    const removedAt = Date.parse(entry.deprecatedAt ?? "");
    if (Number.isNaN(removedAt) || now - removedAt > DEPRECATED_MODEL_TTL_MS) continue;
    const model = { ...entry } as JsonModel & { deprecatedAt?: string };
    delete model.deprecatedAt;
    result.push(model);
  }
  return result;
}

// Append grace-period deprecated models the list does not already have (live data wins).
function withDeprecated(models: JsonModel[]): JsonModel[] {
  const seen = new Set(models.map((m) => m.id));
  const extras = activeDeprecatedModels().filter((m) => !seen.has(m.id));
  return extras.length > 0 ? [...models, ...extras] : models;
}

function loadStaleModels(embeddedModels: JsonModel[]): JsonModel[] {
  markCacheLoaded(CACHE_PATH); // stat before read: lets session_start spot newer caches
  const cached = loadCachedModels();
  if (!cached || cached.length === 0) return embeddedModels;

  // Merge embedded models that are missing from cache (newly added models)
  const cachedMap = new Map(cached.map(m => [m.id, m]));
  for (const em of embeddedModels) {
    if (!cachedMap.has(em.id)) {
      cached.push(em);
    }
  }
  return cached;
}

/**
 * Background revalidation, gated by the quiet startup sync policy
 * (sync-policy.ts): no key → no fetch; fresh cache (TTL) → no fetch; another
 * process already fetching → no fetch. When skipped, a cache that another
 * process refreshed since we loaded it is adopted from disk instead.
 * `force` bypasses the TTL (e.g. after /login); it is still single-flight.
 */
async function revalidateModels(apiKey: string | undefined, embeddedModels: JsonModel[], signal?: AbortSignal, force = false): Promise<JsonModel[] | null> {
  const lease = acquireModelSync({ cachePath: CACHE_PATH, apiKey, force });
  if (!lease) return cacheChangedSinceLoad(CACHE_PATH) ? loadStaleModels(embeddedModels) : null;
  let merged: JsonModel[] | null = null;
  try {
    const liveModels = apiKey ? await fetchLiveModels(apiKey, signal) : null;
    if (!liveModels || liveModels.length === 0) return null;
    merged = mergeWithEmbedded(liveModels, embeddedModels);
    cacheModels(merged);
    return merged;
  } finally {
    lease.release(merged ? "fetched" : signal?.aborted ? "aborted" : "failed");
  }
}

// ─── API Key Resolution (via ModelRegistry) ────────────────────────────────────

let cachedApiKey: string | undefined;
let revalidateAbort: AbortController | null = null;

async function resolveApiKey(modelRegistry: ModelRegistry): Promise<void> {
  cachedApiKey = await modelRegistry.getApiKeyForProvider("opencode") ?? undefined;
}

// ─── Extension Entry Point ────────────────────────────────────────────────────

// Legacy provider registrations replace all operations in Pi 1.0. Preserve
// native image/classifier models and their implementations, rather than reviving
// old cached Jev entries as zero-output chat models.
export function providerModels(models: JsonModel[]): NonNullable<ProviderConfig["models"]> {
  const nonChat = getAllBuiltinModels("opencode").filter(model => model.type !== "chat");
  const nonChatIds = new Set(nonChat.map(model => model.id));
  return [
    // Old catalogs include retired Jev aliases with maxTokens:0. Even when
    // absent from the native classifier catalog, they must never become chat models.
    ...models.filter(model => !nonChatIds.has(model.id) && model.maxTokens > 0).map(model => ({ ...model, api: model.api ?? "openai-completions" as const })),
    ...nonChat,
  ];
}

export default function (pi: ExtensionAPI) {
  const embeddedModels = modelsData as JsonModel[];
  const customModels = customModelsData as JsonModel[];
  const patches = patchData as PatchData;

  const staleBase = loadStaleModels(embeddedModels);
  const staleModels = buildModels(staleBase, customModels, patches);

  pi.registerProvider("opencode", {
    name: "OpenCode Zen",
    baseUrl: BASE_URL,
    apiKey: "$OPENCODE_API_KEY",
    api: "openai-completions",
    models: providerModels(staleModels),
  });

  // Fire-and-forget: never await network here — startup must not block on the
  // provider API. Nothing is awaited and every rejection is swallowed.
  pi.on("session_start", async (_event, ctx) => {
    revalidateAbort?.abort();
    revalidateAbort = new AbortController();
    const signal = revalidateAbort.signal;
    void resolveApiKey(ctx.modelRegistry)
      .then(() => revalidateModels(cachedApiKey, embeddedModels, signal))
      .then((freshBase) => {
        if (freshBase && !signal.aborted) {
          pi.registerProvider("opencode", {
            name: "OpenCode Zen",
            baseUrl: BASE_URL,
            apiKey: "$OPENCODE_API_KEY",
            api: "openai-completions",
            models: providerModels(buildModels(freshBase, customModels, patches)),
          });
        }
      })
      .catch(() => { /* keep serving the stale catalog */ });
  });

  pi.on("session_shutdown", () => {
    revalidateAbort?.abort();
  });
}
